import React from "react";
import { BrowserRouter as Router, Routes, Route, useLocation } from "react-router-dom";
import PrivateRoute from "./utils/PrivateRoute";  // Import PrivateRoute
import HomePage from "./pages/HomePage";
import LoginPage from "./pages/LoginPage";
import RegisterPage from "./pages/RegisterPage";
import UserListPage from "./pages/UserListPage";
import Navbar from "./components/Navbar";
import HealthCheck from './utils/ApiHealthCheck';
import NotFound from "./pages/NotFound";
import SessionUtil from "./utils/SessionUtil";

const AppWithNavbar: React.FC = () => {
  const location = useLocation();
  const routesWithoutNavbar = ["/login", "/register", "/"];
  const showNavbar = !routesWithoutNavbar.includes(location.pathname);

  return (
    <div className="flex">
      <SessionUtil timeoutInMinutes={1} />
      {showNavbar && <Navbar />}
      <div className="flex-1 p-6">
        <Routes>
          <Route path="/" element={<HomePage />} />
          <Route path="/login" element={<LoginPage />} />
          <Route path="/register" element={<RegisterPage />} />

          {/* Protected route, only accessible if user is logged in */}
          <Route
            path="/users"
            element={
              <PrivateRoute element={<UserListPage />} />
            }
          />

          <Route path="/*" element={<NotFound />} />
        </Routes>
      </div>
    </div>
  );
};

const App: React.FC = () => {
  return (
      <Router>
        <HealthCheck>
          <AppWithNavbar />
        </HealthCheck>
      </Router>
  );
};

export default App;
